import { DestructiveConfirmationInput } from '@vercel/geistcn/components';
import { useState, type JSX } from 'react';

const VERIFICATION_PHRASE = 'next-year-boilerplate';

export function Component(): JSX.Element {
  const [value, setValue] = useState('next-year');
  const [touched, setTouched] = useState(true);
  const mismatch = touched && value !== '' && value !== VERIFICATION_PHRASE;

  return (
    <div className="w-full max-w-[420px]">
      <DestructiveConfirmationInput
        error={mismatch ? 'The project name must match exactly.' : null}
        onBlur={() => setTouched(true)}
        onChange={(e) => {
          setValue(e.target.value);
          setTouched(false);
        }}
        value={value}
        verificationLabel="project name"
        verificationPhrase={VERIFICATION_PHRASE}
      />
    </div>
  );
}

